**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
using namespace std;

int main() {
    ifstream plik("dane.txt");
    int liczba;
    int ile = 0;
    while (plik >> liczba) {
        int freq[10] = {0};
        int kopia = liczba;
        while (kopia > 0) {
            freq[kopia % 10]++;
            kopia /= 10;
        }
        int powtorzona = -1;
        for (int i = 0; i <= 9; i++) {
            if (freq[i] > 1) {
                powtorzona = i;
                break;
            }
        }
        cout << liczba;
        if (powtorzona == -1) {
            cout << " -> wszystkie cyfry rozne -> TAK" << endl;
            ile++;
        } else {
            cout << " -> cyfra " << powtorzona << " powtorzona -> NIE" << endl;
        }
    }
    cout << "Liczb z unikalnymi cyframi: " << ile << endl;
    return 0;
}
```

**Wyjasnienie**: Tablica `freq[10]` zlicza wystapienia kazdej cyfry (0-9). Po przetworzeniu wszystkich cyfr, jesli jakikolwiek element > 1, to cyfra sie powtarza. Szukamy pierwszej powtorzonej (od 0 w gore).

